#include <vector>
#include <unordered_map>

using namespace std;

class Solution {
public:
    int maxOperations(vector<int>& nums, int k) {
        unordered_map<int, int> count;
        int res = 0;
        for (int n : nums) {
            if (count[k - n] > 0) {
                res++;
                count[k - n]--;
            } else {
                count[n]++;
            }
        }
        return res;
    }
};
